    ["note_drops_sflow"] = "丢弃仅针对 sFlow 显示，因为 NetFlow 不会报告它们。<br><A HREF=https://www.ietf.org/rfc/rfc3176.txt>sFlow</A> drops 指的是sFlow代理检测到标记为要采样的数据包由于缺乏资源而被放弃的次数。丢弃计数器报告自代理上次重置以来检测到的丢弃总数。一个高的丢弃率表明管理代理无法以硬件产生的速度来处理样本。增加sFlow采样率将减少丢弃率。注意：一个不能检测到丢包的代理将总是报告为零。",
    ["note_lifetime_timeout"] = "无论流持续时间如何，活动时间超过指定最大值 <A HREF=https://www.ntop.org/guides/nprobe/cli_options.html?highlight=maximum%20flow%20lifetime>lifetime</A> 的流将被视为已过期，并将被发出（nProbe -t 选项）",
    ["note_packets"] = "在以太网网络中，每个数据包都有一个 <A HREF=\"https://en.wikipedia.org/wiki/Ethernet_frame\">24 字节的开销</A> [前导（7 字节）,帧开始（1 字节）、CRC（4 个字节）和 <A HREF=\"http://en.wikipedia.org/wiki/Interframe_gap\">IFG</A>（12 个字节）]。 此类开销需要计入接口流量，但不会添加到 IP 地址之间交换的流量中。 这是因为此类数据会增加接口负载，但无法计入主机交换的流量中，因此预计主机和接口流量值之间的差异很小。",
