    ["toggle_top_sites_description"] = "启用本地主机访问网站排行的创建。排行通过<a href=\"%{url}\">启发式算法</a>生成，每个本地主机最多保留 20 个网站。该算法完全运行于内存中，无需磁盘交互。访问网站排行每 5 分钟清理一次。可通过定期轮询主机详情页面中的 JSON <i class=\"fas fa-download fa-sm\"></i> 下载链接，为每个本地主机创建历史访问网站存档。支持的网站应用协议包括：TLS、QUIC、HTTP 和 DNS。",
